function workSurface(id,step) {
 return ({priya:financeWork,ben:benWork,nina:ninaWork,marcus:marcusWork,ava:avaWork,elena:elenaWork,daniel:danielWork,dana:danaWork,leah:leahWork})[id](step);
}
function peerWork(id,story) {
 const preview=id==='priya'?`<ul class="ws-checklist"><li>Rename Supplier to Vendor</li><li>Correct ACME LTD. spelling</li><li>Check invoice N101 against other files</li></ul><p class="ws-peer-final">Maya does not know the method exists.</p>`
  :id==='ben'?`<ul class="ws-checklist ws-checked"><li>This week: $2.4m <b>✓</b></li><li>Last week: $2.5m <b>✓</b></li></ul><p class="ws-peer-broken">Dates moved twice: Not compared ✕</p>`
  :id==='nina'?`<p class="ws-peer-text">A service manager opens the same cases individually to prepare her weekly summary.</p>`
  :`<p class="ws-peer-text">“Could I practice before my next call?”</p>`;
 const who=id==='priya'?ghost('Maya · other branch'):id==='nina'?`<span class="ws-ghost">${avatar('ava','ws-avatar-peer')}<b>Service (Ava’s team)</b></span>`:ghost('');
 return `<div class="ws-peer peer-task"><small>WHO ELSE COULD USE THIS?</small><div class="ws-peer-link">${avatar(id,'ws-avatar-peer')}<i class="ws-broken"><em>✕</em></i>${who}</div>${id==='priya'?'':`<h3>${story.peerTitle}</h3>`}${preview}</div>`;
}
function stops(id,story,peer) {
 const p=person(id);const v=verdicts[id];
 let main=`<p class="ws-stops-main">${story.consequence}</p>`;
 if(id==='ava')main=`<p class="ws-stops-main">Finding the facts still required six records.</p><p class="ws-stops-sub">${story.consequence}</p>`;
 if(id==='elena')main=`<p class="ws-stops-main">She returned to manual updates.</p><small>WHAT SHE NEEDS</small><p class="ws-stops-sub">A guided review of her actual notes and tracker would give her a useful starting point.</p>`;
 const extra=id==='dana'?`<p class="ws-foreshadow">${ghost('')}Her weekly brief is assembled by Leah →</p>`:'';
 return `<section class="ws-block-a v-${v}"><small>${v==='stuck'?`What ${p.name} tried`:`What AI does for ${p.name}`}</small><p>${story.situation}</p></section><section class="ws-block-b"><small>${deadEnd}Where it stops</small>${main}${extra}${peer?peerWork(id,story):''}</section>`;
}
function leahFunnel(state,story) {
 const inbound=[['ben','Sales','Atlas moved. <span class="ws-conflict">Which forecast version?</span>'],['nina','Operations','“<span class="ws-conflict">Northwind</span> setup came back.”'],['ava','Service','“<span class="ws-conflict">NW Services</span>. Update <span class="ws-conflict">Tuesday</span>.”']];
 return `<section class="employee-workspace ws-leah"><div class="ws-funnel"><div class="ws-inbound"><small>LEAH’S MANUAL RECONCILIATION</small>${inbound.map(([id,dept,text])=>`<div class="ws-inbox">${personToken(id,'S')}<p><b>${dept}</b> ${text}</p></div>`).join('')}</div><svg class="ws-arrows" viewBox="0 0 100 100" preserveAspectRatio="none" aria-hidden="true"><path d="M0 25 C60 25 40 16 100 16M0 54 C60 54 40 16 100 16M0 83 C60 83 40 16 100 16" vector-effect="non-scaling-stroke"/></svg><div class="ws-leah-mid">${personToken('leah','L')}<blockquote>${story.quote}</blockquote><ul class="ws-questions"><li>Same customer?</li><li>Which Tuesday?</li><li><b>Who owns the next step?</b></li></ul></div><svg class="ws-arrows ws-arrow-out" viewBox="0 0 100 100" preserveAspectRatio="none" aria-hidden="true"><path d="M0 16 L100 16" vector-effect="non-scaling-stroke"/></svg><div class="ws-dana-sees">${frame('ms-powerpoint.svg','What Dana sees','Friday brief',`<p class="ws-brief">“Sales revised its forecast. Operations handled 18 escalations. Service responded to every inquiry.”</p><p class="ws-brief-note">Copilot polished the wording. Leah still had to reconcile the facts, and the potential cross-team pattern is absent.</p><div class="ws-to-dana"><span>→</span>${personToken('dana','S')}</div>`,'leah')}</div></div><p class="ws-thesis">Everyone has AI. The wins are real. <b>Nothing is connected.</b></p>${actions('leah',state,true)}${employeeStrip('leah')}</section>`;
}
function actions(id,state,done) {
 const step=state.workSteps?.[id]||0;
 return `<div class="workspace-actions ws-actions">${id==='marcus'?`<button class="primary" data-work-action="marcus">${step?'Replay captioned practice':'Play captioned practice'}</button>`:done?'':`<button class="primary" data-work-reveal="${id}">Show ${person(id).name}’s work</button>`}<button data-close-workspace>← Company view</button></div>`;
}
export function renderWorkspace(state,personId=state.workspace||state.person) {
 const p=person(personId)||person('priya');const id=p.id;const story=workspaceStories[id];const step=state.workSteps?.[id]||0;
 const done=step>=story.max;const peer=done&&story.peer;
 if(id==='leah'&&done)return leahFunnel(state,story);
 return `<section class="employee-workspace ws-${id}"><header class="ws-head">${personToken(id,'L')}<div class="ws-quote"><small>The nine · Person ${tourOrder.indexOf(id)+1} of 9</small><blockquote>${story.quote}</blockquote></div></header><div class="ws-columns"><section class="ws-surface">${workSurface(id,step)}</section><aside class="ws-side">${stops(id,story,peer)}${actions(id,state,done)}</aside></div>${employeeStrip(id)}</section>`;
}
export function workspaceHeading(state) {const id=state.workspace||state.person;return workspaceStories[id]?.title;}
